const tabId = 1962625075;

const quotes = await browserjs(tabId, () => {
  const table = document.querySelector('table.dataTable.full');
  if (!table) return [];

  // Each main rate row has 3 cells: Service, Time, Cost
  const rows = Array.from(table.querySelectorAll('tr'));
  const results = [];

  for (const tr of rows) {
    const tds = Array.from(tr.children);
    if (tds.length === 3 && tds[0].tagName === 'TD') {
      const serviceText = tds[0].innerText.trim();
      const timeText = tds[1].innerText.trim();
      const costText = tds[2].innerText.trim();

      // Extract service name (first line)
      const serviceLines = serviceText.split('\n').map(s => s.trim()).filter(Boolean);
      const serviceName = serviceLines[0] || serviceText;

      // Extract delivery commitment
      const timeLines = timeText.split('\n').map(s => s.trim()).filter(Boolean);

      // Extract cost
      const costMatch = costText.match(/([\d,.]+\s*USD)/i) || costText.match(/\$?\s*([\d,.]+)/);
      const cost = costMatch ? costMatch[0] : costText.split('\n')[0];

      results.push({
        service: serviceName,
        serviceFull: serviceText,
        time: timeText,
        cost: cost,
        costFull: costText
      });
    }
  }
  return results;
});

console.log("Structured Quotes:", JSON.stringify(quotes, null, 2));

